pages.source:
Page(name: "Password reset", route: Route(path: "/reset-password"))

Build(
  Scaffold(
    appBar: BentoBoxHeader(),
    body: ScrollView(label: "Password reset", child: Column(gap: Space.md, padding: Insets(y: 12), children: [Column(gap: Space.xl, padding: Insets(x: 24, y: 8), children: [
    Box(padding: Space.xl, radius: Radius.none, background: Color.primary, child: Column(gap: Space.sm, children: [Text(child: "SECURITY", size: FontSize.xs, weight: FontWeight.bold, letterSpacing: 3, color: Color.primaryInk), Text(child: "RESET YOUR PASSWORD", size: FontSize.xxl, weight: FontWeight.bold, color: Color.primaryInk)])), Form(id: "resetPassword", onSubmit: ResetPreviewPassword(), child: Column(gap: Space.md, children: [TextField(name: "email", label: "Your email", type: InputType.email, required: true, background: Color.surface, border: Border(width: 1, color: Color.border), radius: Radius.none), SubmitButton(label: "SEND RESET LINK", fullWidth: true)])), Button(label: "BACK TO THE MENU", style: ButtonStyle.ghost, icon: Icons.chevronLeft, onTap: Navigate(to: Route.menu))
  ])])),
  )
)
